<template><div class="page-container watchlist-page"><PageHeader title="Hàng đợi watchlist" description="Rà soát cảnh báo trùng khớp và quản lý đối tượng cần giám sát theo mức độ rủi ro." :breadcrumbs="[{label:'Giám sát'},{label:'Watchlist'}]"><template #actions><BaseButton variant="secondary" :loading="loading" @click="loadActive">Làm mới</BaseButton><BaseButton @click="openAddEntry">Thêm đối tượng</BaseButton></template></PageHeader>
<BaseTabs v-model="activeTab" :items="tabItems" aria-label="Nội dung watchlist" id-prefix="watchlist" @update:model-value="commitTab"/>
<section v-if="activeTab==='matches'" id="watchlist-panel-matches" role="tabpanel" aria-labelledby="watchlist-tab-matches" class="queue-panel"><header><div><h2>Cảnh báo trùng khớp</h2><p>{{ matches.length }} bản ghi trong trang hiện tại</p></div><div class="filters"><BaseInput id="watchlist-status-search" v-model="filterStatus" type="search" aria-label="Tìm trạng thái" placeholder="Tìm trạng thái"/><BaseSelect id="watchlist-severity" v-model="severityFilter" aria-label="Lọc mức độ" @update:model-value="commitFilters"><option value="">Tất cả mức độ</option><option value="Critical">Nghiêm trọng</option><option value="High">Cao</option><option value="Medium">Trung bình</option><option value="Low">Thấp</option></BaseSelect></div></header>
<DataTable :columns="matchColumns" :rows="filteredMatches" row-key="watchlistMatchId" :loading="loading" :error="loadError" :permission-denied="permissionDenied" empty-title="Không có cảnh báo watchlist" empty-description="Không có bản ghi phù hợp với bộ lọc hiện tại."><template #retry><BaseButton variant="secondary" @click="loadMatches">Thử lại</BaseButton></template><template #cell-severity="{row}"><StatusBadge :status="severitySemantic(row.watchlistEntry?.severity)" :label="severityLabel(row.watchlistEntry?.severity)" dot/></template><template #cell-entry="{row}"><div class="stacked"><strong>{{ row.watchlistEntry?.displayName||'—' }}</strong><small>{{ row.watchlistEntry?.reason||'Không có lý do' }}</small></div></template><template #cell-visitor="{row}"><BaseButton variant="link" size="small" @click="visitorDetail=row.visit">{{ row.visit?.visitorName||'Chưa xác định' }}</BaseButton></template><template #cell-matchedAtUtc="{value}">{{ formatDate(value) }}</template><template #cell-status="{row}"><div class="status-cell"><StatusBadge :status="matchStatusSemantic(row.status)" :label="statusLabel(row.status)" dot/><small v-if="row.status==='Pending'">{{ hoursSince(row.matchedAtUtc) }} giờ</small></div></template><template #actions="{row}"><BaseButton variant="ghost" size="small" @click="openReview(row)">Kiểm duyệt</BaseButton></template></DataTable><footer v-if="!loading&&!loadError&&totalPages>1" class="pagination"><BaseButton variant="secondary" size="small" :disabled="page<=1" @click="setPage(page-1)">Trang trước</BaseButton><span>{{ page }} / {{ totalPages }}</span><BaseButton variant="secondary" size="small" :disabled="page>=totalPages" @click="setPage(page+1)">Trang sau</BaseButton></footer></section>
<section v-else id="watchlist-panel-entries" role="tabpanel" aria-labelledby="watchlist-tab-entries" class="queue-panel"><header><div><h2>Danh mục watchlist</h2><p>{{ filteredEntries.length }} đối tượng đang hoạt động</p></div><BaseInput id="watchlist-entry-search" v-model="entrySearch" type="search" aria-label="Tìm đối tượng" placeholder="Tên, định danh hoặc lý do"/></header><DataTable :columns="entryColumns" :rows="filteredEntries" row-key="watchlistEntryId" :loading="loading" :error="loadError" :permission-denied="permissionDenied" empty-title="Chưa có đối tượng watchlist" empty-description="Thêm đối tượng để bắt đầu theo dõi cảnh báo."><template #retry><BaseButton variant="secondary" @click="loadEntries">Thử lại</BaseButton></template><template #empty-actions><BaseButton @click="openAddEntry">Thêm đối tượng</BaseButton></template><template #cell-displayName="{row}"><div class="stacked"><strong>{{ row.displayName }}</strong><small>{{ row.reason||'Không có lý do' }}</small></div></template><template #cell-identifier="{value}">{{ value||'—' }}</template><template #cell-severity="{value}"><StatusBadge :status="severitySemantic(value)" :label="severityLabel(value)" dot/></template><template #cell-isActive="{value}"><StatusBadge :status="value?'active':'inactive'" :label="value?'Hoạt động':'Ngừng theo dõi'" dot/></template></DataTable></section>
<BaseModal :open="Boolean(reviewMatch)" title="Kiểm duyệt cảnh báo watchlist" :description="`${reviewMatch?.watchlistEntry?.displayName||''} · ${reviewMatch?.visit?.visitorName||''}`" @close="reviewMatch=null"><form id="watchlist-review-form" class="modal-form" @submit.prevent="submitReview"><dl class="review-summary"><div><dt>Mức độ</dt><dd><StatusBadge :status="severitySemantic(reviewMatch?.watchlistEntry?.severity)" :label="severityLabel(reviewMatch?.watchlistEntry?.severity)"/></dd></div><div><dt>Trùng khớp lúc</dt><dd>{{ formatDate(reviewMatch?.matchedAtUtc) }}</dd></div></dl><BaseField for-id="watchlist-decision" label="Quyết định" required v-slot="field"><BaseSelect id="watchlist-decision" v-model="reviewDecision" :describedby="field.describedby"><option value="Confirmed">Xác nhận cảnh báo</option><option value="FalsePositive">Sai dương</option><option value="Escalated">Chuyển cấp</option><option value="Closed">Đóng</option></BaseSelect></BaseField><BaseField for-id="watchlist-note" label="Ghi chú" :counter="`${reviewNote.length}/500`" v-slot="field"><BaseTextarea id="watchlist-note" v-model="reviewNote" maxlength="500" :describedby="field.describedby"/></BaseField><p v-if="formError" class="form-error" role="alert">{{ formError }}</p></form><template #footer><BaseButton variant="secondary" :disabled="saving" @click="reviewMatch=null">Hủy</BaseButton><BaseButton type="submit" form="watchlist-review-form" :loading="saving">Gửi kết quả</BaseButton></template></BaseModal>
<BaseModal :open="showAddEntry" title="Thêm đối tượng watchlist" description="Đối tượng mới sẽ được kích hoạt ngay sau khi lưu." @close="requestCloseEntry"><form id="watchlist-entry-form" class="modal-form" @submit.prevent="submitEntry"><BaseField for-id="watchlist-name" label="Tên hiển thị" required :error="entrySubmitted&&!newEntry.name.trim()?'Tên đối tượng là bắt buộc.':''" v-slot="field"><BaseInput id="watchlist-name" v-model="newEntry.name" :describedby="field.describedby" :invalid="field.invalid"/></BaseField><div class="form-grid"><BaseField for-id="watchlist-type" label="Loại" v-slot="field"><BaseSelect id="watchlist-type" v-model="newEntry.entityType" :describedby="field.describedby"><option value="Person">Con người</option><option value="Vehicle">Phương tiện</option></BaseSelect></BaseField><BaseField for-id="watchlist-identifier" label="Định danh" v-slot="field"><BaseInput id="watchlist-identifier" v-model="newEntry.identifier" :describedby="field.describedby" placeholder="SĐT, biển số hoặc ID"/></BaseField><BaseField for-id="watchlist-new-severity" label="Mức độ" v-slot="field"><BaseSelect id="watchlist-new-severity" v-model="newEntry.severity" :describedby="field.describedby"><option value="Low">Thấp</option><option value="Medium">Trung bình</option><option value="High">Cao</option><option value="Critical">Nghiêm trọng</option></BaseSelect></BaseField><BaseField for-id="watchlist-reason" label="Lý do" v-slot="field"><BaseInput id="watchlist-reason" v-model="newEntry.reason" :describedby="field.describedby"/></BaseField></div><p v-if="formError" class="form-error" role="alert">{{ formError }}</p></form><template #footer><BaseButton variant="secondary" :disabled="saving" @click="requestCloseEntry">Hủy</BaseButton><BaseButton type="submit" form="watchlist-entry-form" :loading="saving">Thêm đối tượng</BaseButton></template></BaseModal>
<BaseModal :open="Boolean(visitorDetail)" title="Chi tiết khách" description="Thông tin chuyến thăm liên quan đến cảnh báo." @close="visitorDetail=null"><dl v-if="visitorDetail" class="visitor-detail"><div><dt>Họ tên</dt><dd>{{ visitorDetail.visitorName||'—' }}</dd></div><div><dt>Điện thoại</dt><dd>{{ visitorDetail.visitorPhone||'—' }}</dd></div><div><dt>Chủ nhà</dt><dd>{{ visitorDetail.hostEmployee?.fullName||'—' }}</dd></div><div><dt>Trạng thái</dt><dd><StatusBadge :status="visitStatusSemantic(visitorDetail.status)" :label="visitorDetail.status||'Không rõ'"/></dd></div></dl><template #footer><BaseButton variant="secondary" @click="visitorDetail=null">Đóng</BaseButton></template></BaseModal>
<ConfirmDialog :open="showDiscard" title="Bỏ đối tượng đang nhập?" description="Thông tin watchlist chưa lưu sẽ bị mất." confirm-label="Bỏ thay đổi" @cancel="showDiscard=false" @confirm="closeEntry(true)"/></div></template>
<script setup>import{computed,onMounted,reactive,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{enterpriseApi}from'../services/enterpriseSecurityApi';import BaseButton from'../components/ui/BaseButton.vue';import BaseField from'../components/ui/BaseField.vue';import BaseInput from'../components/ui/BaseInput.vue';import BaseModal from'../components/ui/BaseModal.vue';import BaseSelect from'../components/ui/BaseSelect.vue';import BaseTabs from'../components/ui/BaseTabs.vue';import BaseTextarea from'../components/ui/BaseTextarea.vue';import ConfirmDialog from'../components/ui/ConfirmDialog.vue';import DataTable from'../components/ui/DataTable.vue';import PageHeader from'../components/ui/PageHeader.vue';import StatusBadge from'../components/ui/StatusBadge.vue';import{useToasts}from'../composables/useToasts';
const route=useRoute(),router=useRouter(),{success}=useToasts();const loading=ref(true),saving=ref(false),loadError=ref(''),permissionDenied=ref(false),activeTab=ref('matches'),matches=ref([]),entries=ref([]),page=ref(1),totalPages=ref(1),filterStatus=ref(''),severityFilter=ref(''),entrySearch=ref(''),reviewMatch=ref(null),reviewDecision=ref('Confirmed'),reviewNote=ref(''),showAddEntry=ref(false),visitorDetail=ref(null),formError=ref(''),entrySubmitted=ref(false),showDiscard=ref(false),entryBaseline=ref('');const newEntry=reactive({name:'',entityType:'Person',identifier:'',severity:'Medium',reason:''});const matchColumns=[{key:'severity',label:'Mức độ'},{key:'entry',label:'Đối tượng'},{key:'visitor',label:'Khách'},{key:'matchedAtUtc',label:'Thời gian'},{key:'status',label:'Trạng thái'}],entryColumns=[{key:'displayName',label:'Đối tượng'},{key:'entityType',label:'Loại'},{key:'identifier',label:'Định danh'},{key:'severity',label:'Mức độ'},{key:'isActive',label:'Theo dõi'}];const tabItems=computed(()=>[{value:'matches',label:'Cảnh báo',count:matches.value.length},{value:'entries',label:'Đối tượng',count:entries.value.length}]);const filteredMatches=computed(()=>matches.value.filter(item=>(!filterStatus.value||String(item.status).toLowerCase().includes(filterStatus.value.toLowerCase()))&&(!severityFilter.value||item.watchlistEntry?.severity===severityFilter.value)));const filteredEntries=computed(()=>{const q=entrySearch.value.toLowerCase();return entries.value.filter(item=>!q||[item.displayName,item.identifier,item.reason].some(value=>String(value||'').toLowerCase().includes(q)))});const entryState=computed(()=>JSON.stringify(newEntry));const entryDirty=computed(()=>showAddEntry.value&&entryState.value!==entryBaseline.value)
function applyQuery(){activeTab.value=route.query.tab==='entries'?'entries':'matches';severityFilter.value=String(route.query.severity||'');page.value=Math.max(1,Number(route.query.page)||1)}function commitTab(){router.replace({query:{...route.query,tab:activeTab.value==='entries'?'entries':undefined,page:undefined,severity:activeTab.value==='matches'?severityFilter.value||undefined:undefined}})}function commitFilters(){router.replace({query:{...route.query,severity:severityFilter.value||undefined,page:undefined}})}function setPage(next){router.replace({query:{...route.query,page:next>1?next:undefined}})}async function loadMatches(){loading.value=true;loadError.value='';permissionDenied.value=false;try{const data=(await enterpriseApi.getWatchlistMatches({page:page.value,pageSize:25,severity:severityFilter.value||undefined})).data||{};matches.value=data.items||[];totalPages.value=Math.max(1,Math.ceil((data.total||0)/25))}catch(error){matches.value=[];if(error.response?.status===403)permissionDenied.value=true;else loadError.value=error.response?.data?.message||'Không thể tải cảnh báo watchlist.'}finally{loading.value=false}}async function loadEntries(){loading.value=true;loadError.value='';permissionDenied.value=false;try{entries.value=(await enterpriseApi.getWatchlistEntries({active:true})).data||[]}catch(error){entries.value=[];if(error.response?.status===403)permissionDenied.value=true;else loadError.value=error.response?.data?.message||'Không thể tải danh mục watchlist.'}finally{loading.value=false}}function loadActive(){return activeTab.value==='matches'?loadMatches():loadEntries()}
function openReview(item){reviewMatch.value=item;reviewDecision.value=item.status==='Pending'?'Confirmed':item.status;reviewNote.value='';formError.value=''}async function submitReview(){if(!reviewMatch.value)return;saving.value=true;formError.value='';try{await enterpriseApi.reviewWatchlistMatch(reviewMatch.value.watchlistMatchId,{status:reviewDecision.value,reviewNote:reviewNote.value||null});reviewMatch.value=null;success('Đã cập nhật cảnh báo watchlist');await loadMatches()}catch(error){formError.value=error.response?.data?.message||'Không thể lưu kết quả. Ghi chú vẫn được giữ lại.'}finally{saving.value=false}}function openAddEntry(){Object.assign(newEntry,{name:'',entityType:'Person',identifier:'',severity:'Medium',reason:''});entrySubmitted.value=false;formError.value='';showAddEntry.value=true;queueMicrotask(()=>{entryBaseline.value=entryState.value})}function requestCloseEntry(){if(entryDirty.value){showDiscard.value=true;return}closeEntry(true)}function closeEntry(force=false){if(!force&&entryDirty.value)return requestCloseEntry();showAddEntry.value=false;showDiscard.value=false;formError.value=''}async function submitEntry(){entrySubmitted.value=true;if(!newEntry.name.trim())return;saving.value=true;formError.value='';try{await enterpriseApi.createWatchlistEntry({entityType:newEntry.entityType,displayName:newEntry.name.trim(),identifier:newEntry.identifier||null,severity:newEntry.severity,reason:newEntry.reason||'Security watchlist'});closeEntry(true);success('Đã thêm đối tượng watchlist');if(activeTab.value==='entries')await loadEntries()}catch(error){formError.value=error.response?.data?.message||'Không thể thêm đối tượng. Thông tin vẫn được giữ lại.'}finally{saving.value=false}}
function severitySemantic(value){return value==='Critical'?'critical':value==='High'?'danger':value==='Medium'?'warning':'info'}function severityLabel(value){return{Critical:'Nghiêm trọng',High:'Cao',Medium:'Trung bình',Low:'Thấp'}[value]||value||'Không rõ'}function matchStatusSemantic(value){return value==='Pending'?'warning':value==='Confirmed'?'critical':value==='FalsePositive'?'info':'success'}function statusLabel(value){return{Pending:'Chờ xử lý',Confirmed:'Đã xác nhận',FalsePositive:'Sai dương',Escalated:'Chuyển cấp',Closed:'Đã đóng'}[value]||value}function visitStatusSemantic(value){return value==='CheckedIn'?'success':value==='Overstay'?'critical':value==='Approved'?'info':'neutral'}function formatDate(value){return value?new Date(value).toLocaleString('vi-VN'):'—'}function hoursSince(value){return value?Math.max(0,Math.round((Date.now()-new Date(value).getTime())/3600000)):0}onMounted(()=>{applyQuery();loadActive()});watch(()=>route.query,()=>{applyQuery();loadActive()},{deep:true})</script>
<style scoped>.watchlist-page{display:grid;gap:var(--space-6)}.queue-panel{display:grid;gap:var(--space-4)}.queue-panel>header{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--space-4)}.queue-panel h2{font-size:var(--type-h2-size)}.queue-panel header p,.stacked small{color:var(--text-muted);font-size:var(--type-body-size)}.filters{display:grid;grid-template-columns:1fr 180px;gap:var(--space-2);width:min(100%,520px)}.stacked,.modal-form{display:grid;gap:var(--space-2)}.status-cell{display:grid;gap:var(--space-1)}.status-cell small{color:var(--text-muted);font-size:var(--type-caption-size)}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:var(--space-3)}.review-summary,.visitor-detail{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-3);margin:0}.review-summary div,.visitor-detail div{display:grid;gap:var(--space-1);padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-control);background:var(--surface-subtle)}.review-summary dt,.visitor-detail dt{color:var(--text-muted);font-size:var(--type-caption-size)}.review-summary dd,.visitor-detail dd{margin:0;font-weight:700}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-3)}.form-error{padding:var(--space-3);border:1px solid var(--status-danger-border);border-radius:var(--radius-control);background:var(--status-danger-bg);color:var(--status-danger-text)}@media(max-width:800px){.queue-panel>header{align-items:stretch;display:grid}.filters{width:100%}}@media(max-width:640px){.filters,.form-grid,.review-summary,.visitor-detail{grid-template-columns:1fr}}</style>
